script:
res = {}
r = env.run(["find", "src", "-mindepth", "1"], check=False)
res["find_all_entries"] = r.stdout
r2 = env.run(["find", ".", "-type", "l"], check=False)
res["symlinks"] = r2.stdout
res["docs_listing"] = repo.list("docs")
res["final_contents"] = {
    f: repr(repo.read(f))
    for f in ["src/a.txt", "src/nested/b.txt", "src/untouched.txt", "docs/history.txt"]
}
res["byte_counts"] = {
    f: len(repo.read(f))
    for f in ["src/a.txt", "src/nested/b.txt", "src/untouched.txt", "docs/history.txt"]
}
return res
